def minRadius(houses, heaters):
    hs = sorted(houses)
    ht = sorted(heaters)
    m = len(ht)

    def ok(r):
        j = 0
        for x in hs:
            while j < m and ht[j] + r < x:
                j += 1
            if j == m or ht[j] - r > x:
                return False
        return True

    lo, hi = 0, max(hs[-1], ht[-1]) - min(hs[0], ht[0])
    while lo < hi:
        mid = (lo + hi) // 2
        if ok(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo
